}
function SetArchiveDuration() {
    const archiveDuration = Variable.GetValueAsString("SupplierInvoice_ArchiveDuration__");
    if (archiveDuration) {
        Data.SetValue("ArchiveDuration", archiveDuration);
    }
}
/**
